import numpy as np, json, math
from PIL import Image
from scipy.ndimage import gaussian_filter, label, binary_closing, distance_transform_edt
im=np.array(Image.open('/app/target.png')).astype(float)
pal=np.array([[216,209,201],[180,178,182],[149,148,153],[163,119,57],[117,119,122],[130,116,93],[83,81,75],[118,60,38],[93,63,47],[49,63,47],[49,44,39],[248,244,236]],float)
# Correct target-label colors (index 0..9 = paints 1..10; 10 = paper). Closest palette.
pal=np.array([[216,209,201],[180,178,182],[149,148,153],[163,119,57],[117,119,122],[130,116,93],[83,81,75],[118,60,38],[93,63,47],[49,44,39],[248,244,236]],float)
labs=np.linalg.norm(im[:,:,None,:]-pal[None,None,:,:],axis=3).argmin(2)
# zhang-suen thinning
def thin(a):
 a=a.astype(np.uint8).copy()
 while True:
  changed=0
  for phase in (0,1):
   p=np.pad(a,1)
   P2=p[:-2,1:-1]; P3=p[:-2,2:]; P4=p[1:-1,2:]; P5=p[2:,2:]; P6=p[2:,1:-1]; P7=p[2:,:-2]; P8=p[1:-1,:-2]; P9=p[:-2,:-2]
   neigh=P2+P3+P4+P5+P6+P7+P8+P9
   seq=[P2,P3,P4,P5,P6,P7,P8,P9,P2]
   trans=sum(((seq[i]==0)&(seq[i+1]==1)) for i in range(8))
   cond=(a==1)&(neigh>=2)&(neigh<=6)&(trans==1)
   if phase==0: cond &= (P2*P4*P6==0)&(P4*P6*P8==0)
   else: cond &= (P2*P4*P8==0)&(P2*P6*P8==0)
   changed+=int(cond.sum()); a[cond]=0
  if changed==0:break
 return a.astype(bool)

def make_graph(sk):
 coords=list(zip(*np.where(sk)))
 S=set(coords); adj={}
 for y,x in coords:
  ns=[]
  for dy in (-1,0,1):
   for dx in (-1,0,1):
    if not(dx or dy):continue
    q=(y+dy,x+dx)
    if q not in S:continue
    if dx and dy and ((y,x+dx) in S or (y+dy,x) in S):continue
    ns.append(q)
  adj[(y,x)]=ns
 return adj

def prune_spurs(adj, maxlen=5):
 adj={k:list(v) for k,v in adj.items()}
 while True:
  remove=set()
  ends=[p for p,n in adj.items() if len(n)==1]
  for start in ends:
   if start not in adj or len(adj[start])!=1:continue
   path=[start]; prev=None;cur=start
   while True:
    ns=[x for x in adj[cur] if x!=prev]
    if len(ns)!=1:break
    nxt=ns[0];path.append(nxt);prev,cur=cur,nxt
    if len(adj[cur])!=2:break
   if len(path)-1<=maxlen and cur in adj and len(adj[cur])>=3:
    remove.update(path[:-1])
  if not remove:break
  for p in remove:
   if p not in adj:continue
   for q in adj[p]:
    if q in adj: adj[q]=[x for x in adj[q] if x!=p]
   del adj[p]
 return adj

def chain_edges(adj):
 crit={p for p,n in adj.items() if len(n)!=2}
 if not crit and adj: crit={min(adj)}
 visited=set(); edges=[]
 def ek(a,b):return (a,b) if a<b else (b,a)
 for c in list(crit):
  for n in adj[c]:
   if ek(c,n) in visited:continue
   path=[c,n];visited.add(ek(c,n));prev,curr=c,n
   while curr not in crit:
    ns=[x for x in adj[curr] if x!=prev]
    if not ns:break
    nxt=ns[0]
    if ek(curr,nxt) in visited:break
    path.append(nxt);visited.add(ek(curr,nxt));prev,curr=curr,nxt
   edges.append(path)
 # catch isolated cycles left if critical set incomplete
 for p,ns in adj.items():
  for n in ns:
   if ek(p,n) in visited:continue
   path=[p,n];visited.add(ek(p,n));prev,curr=p,n
   while True:
    opts=[x for x in adj[curr] if x!=prev]
    if not opts:break
    nxt=opts[0]
    if ek(curr,nxt) in visited:break
    path.append(nxt);visited.add(ek(curr,nxt));prev,curr=curr,nxt
    if curr==p:break
   edges.append(path)
 return edges

def pair_edges(edges):
 inc={}
 for i,p in enumerate(edges):
  inc.setdefault(p[0],[]).append(i);inc.setdefault(p[-1],[]).append(i)
 paired={}
 for v,eids in inc.items():
  tang={}
  for eid in eids:
   p=edges[eid]
   w=p[1] if p[0]==v else p[-2]
   vec=np.array([w[1]-v[1],w[0]-v[0]],float);vec/=np.linalg.norm(vec)+1e-9
   tang[eid]=vec
  unused=set(eids)
  while len(unused)>=2:
   best=None
   for i in unused:
    for j in unused:
     if j<=i:continue
     dot=float(tang[i]@tang[j])
     if dot< -0.15 and (best is None or dot<best[0]):best=(dot,i,j)
   if best is None:break
   _,i,j=best;paired[(v,i)]=j;paired[(v,j)]=i;unused.remove(i);unused.remove(j)
 return paired

def trails_from_edges(edges,paired):
 used=set(); trails=[]
 starts=[]
 for i,p in enumerate(edges):
  for v in (p[0],p[-1]):
   if (v,i) not in paired: starts.append((i,v))
 def walk(eid,start):
  out=[];cur_edge=eid;entry=start
  while cur_edge not in used:
   used.add(cur_edge);p=edges[cur_edge]
   if p[0]==entry: seq=p
   else: seq=p[::-1]
   if out: out.extend(seq[1:])
   else: out.extend(seq)
   exitv=seq[-1]
   nxt=paired.get((exitv,cur_edge))
   if nxt is None or nxt in used:break
   entry=exitv;cur_edge=nxt
  if len(out)>=2: trails.append(np.asarray(out,float))
 for eid,v in starts:
  if eid not in used:walk(eid,v)
 for eid,p in enumerate(edges):
  if eid not in used:walk(eid,p[0])
 return trails

def rdp(points,eps=1.5):
 if len(points)<=2:return points
 a,b=points[0],points[-1];v=b-a
 if np.dot(v,v)==0: d=np.linalg.norm(points-a,axis=1)
 else:
  t=np.clip(((points-a)@v)/(v@v),0,1);d=np.linalg.norm(points-(a+t[:,None]*v),axis=1)
 i=int(np.argmax(d))
 if d[i]<=eps:return np.vstack((a,b))
 return np.vstack((rdp(points[:i+1],eps)[:-1],rdp(points[i:],eps)))

def arc_len(p):return np.linalg.norm(np.diff(p,axis=0),axis=1).sum()
def split_path(p,L=45):
 # interpolate at fixed arc-length interval; keep endpoints and make separate strokes
 seg=np.linalg.norm(np.diff(p,axis=0),axis=1);cum=np.r_[0,np.cumsum(seg)]
 if cum[-1]<1e-6:return []
 starts=np.arange(0,cum[-1],L)
 out=[]
 for st in starts:
  en=min(st+L,cum[-1]); samples=np.linspace(st,en,max(2,int(np.ceil((en-st)/8))+1))
  pts=[]
  for d in samples:
   i=min(np.searchsorted(cum,d,side='right')-1,len(seg)-1); t=(d-cum[i])/(seg[i]+1e-9)
   pts.append(p[i]*(1-t)+p[i+1]*t)
  if en-st>=8:out.append(np.array(pts))
 return out
all_strokes=[];summ=[]
for k in range(10):
 frac=(labs.reshape(512,2,512,2)==k).mean((1,3))
 mask=gaussian_filter(frac,1.0)>.48
 mask=binary_closing(mask,structure=np.ones((3,3)))
 lbl,n=label(mask,structure=np.ones((3,3)));sizes=np.bincount(lbl.ravel());keep=sizes>=8;keep[0]=False;mask=keep[lbl]
 sk=thin(mask)
 dist=distance_transform_edt(mask)
 adj=prune_spurs(make_graph(sk),5)
 edges=chain_edges(adj);paired=pair_edges(edges);trails=trails_from_edges(edges,paired)
 paths=[]
 for tr in trails:
  if len(tr)<2:continue
  tr=rdp(tr,1.5)
  for seg in split_path(tr,45):
   if arc_len(seg)>=8:
    # radii along rounded line from distance field
    radii=[]
    for y,x in seg:
     iy=np.clip(int(round(y)),0,511);ix=np.clip(int(round(x)),0,511);r=dist[iy,ix]
     radii.append(float(r))
    paths.append({'label':k+1,'pts':seg.tolist(),'radius_px':radii,'length_px':float(arc_len(seg))})
 all_strokes+=paths
 lens=np.array([s['length_px'] for s in paths]); rs=np.array([np.median(s['radius_px']) for s in paths])
 summ.append((k+1,len(paths),round(lens.sum(),1),round(lens.mean(),1) if len(lens) else 0, round(np.median(rs),1) if len(rs) else 0))
 print('label',summ[-1])
print('TOTAL',len(all_strokes),'length',sum(x['length_px'] for x in all_strokes))
json.dump(all_strokes,open('/app/output/stroke_paths.json','w'))
